INSERT INTO job_postings (category_id, company_name, title, location, salary_text, source_url, raw_text, status, posted_at) VALUES ((SELECT id FROM job_categories WHERE name = '数据分析师' LIMIT 1), '上海英培商务咨询有限公司（EF 英孚教育）', '数据分析专员 BI Specialist', '上海', '0.8-1.5万/月', NULL, '工作职责：
