INSERT INTO job_postings (category_id, company_name, title, location, salary_text, source_url, raw_text, status, posted_at) VALUES ((SELECT id FROM job_categories WHERE name = '数据分析师' LIMIT 1), '深圳康信润达科技有限公司', '数据分析员', '深圳-龙岗区', '4-8千/月', NULL, '一、岗位要求： excel表格操作熟练，透视分析及基本函数熟练运用
1、负责公司电商商品方面的数据分析(包括库存/销售状况/货品结构等),为公司提供全面的数据分析结果,提出合理化建议,令销售取得更好的经营效益。
