INSERT INTO job_postings (category_id, company_name, title, location, salary_text, source_url, raw_text, status, posted_at) VALUES ((SELECT id FROM job_categories WHERE name = '数据分析师' LIMIT 1), '江苏虫洞电子商务有限公司', '电商数据分析岗', '异地招聘', '5.5-9千/月', NULL, '【岗位需求】跨境电商数据分析管培生
