INSERT INTO job_postings (category_id, company_name, title, location, salary_text, source_url, raw_text, status, posted_at) VALUES ((SELECT id FROM job_categories WHERE name = '数据分析师' LIMIT 1), '东莞新能源科技有限公司', 'IT数据分析 东莞', '东莞-东坑镇', '6-8千/月', NULL, '招聘要求：
