INSERT INTO job_postings (category_id, company_name, title, location, salary_text, source_url, raw_text, status, posted_at) VALUES ((SELECT id FROM job_categories WHERE name = '数据分析师' LIMIT 1), '高顿财经', '财经教育市场推广营销数据分析专员+稳定晋升', '上海-虹口区', '6-8千/月', NULL, '浦东、松江、虹口杨浦皆有岗位招聘
【基本福利待遇】：
