INSERT INTO job_postings (category_id, company_name, title, location, salary_text, source_url, raw_text, status, posted_at) VALUES ((SELECT id FROM job_categories WHERE name = '数据分析师' LIMIT 1), '广州集优电子商务有限公司', '电商运营（数据分析方向）', '广州-海珠区', '5-9千/月', NULL, '岗位职责：
