INSERT INTO job_postings (category_id, company_name, title, location, salary_text, source_url, raw_text, status, posted_at) VALUES ((SELECT id FROM job_categories WHERE name = '数据分析师' LIMIT 1), '广州新普电子科技有限公司', '产品监控员（客服、测试、数据分析）+实习生', '广州-天河区', '3-4.5千/月', NULL, '产品监控员-全职
