INSERT INTO job_postings (category_id, company_name, title, location, salary_text, source_url, raw_text, status, posted_at) VALUES ((SELECT id FROM job_categories WHERE name = '测试工程师' LIMIT 1), '北京华胜天成科技股份有限公司', '测试工程师', '北京', NULL, NULL, '岗位描述：
