INSERT INTO job_postings (category_id, company_name, title, location, salary_text, source_url, raw_text, status, posted_at) VALUES ((SELECT id FROM job_categories WHERE name = '测试工程师' LIMIT 1), '京北方信息技术股份有限公司-深圳分公司', '数据库测试工程师', '深圳-福田区', '1.5-2万/月', NULL, '负责项目数据库测试开发工作
