INSERT INTO job_postings (category_id, company_name, title, location, salary_text, source_url, raw_text, status, posted_at) VALUES ((SELECT id FROM job_categories WHERE name = '测试工程师' LIMIT 1), '丰凯医疗器械（上海）有限公司', '电子设备测试工程师', '上海-浦东新区', '0.8-1万/月', NULL, '岗位职责：
