INSERT INTO job_postings (category_id, company_name, title, location, salary_text, source_url, raw_text, status, posted_at) VALUES ((SELECT id FROM job_categories WHERE name = '测试工程师' LIMIT 1), '佛山智能装备技术研究院', '机器测试工程师', '佛山-南海区', '0.5-1.2万/月', NULL, '1、对机器人产品进行测试，按照测试要求完成测试，提交测试报告，并对结果进行分析；
