INSERT INTO job_postings (category_id, company_name, title, location, salary_text, source_url, raw_text, status, posted_at) VALUES ((SELECT id FROM job_categories WHERE name = '测试工程师' LIMIT 1), '江苏米特物联网科技有限公司', '储能系统测试工程师', '南京', '0.8-1.3万/月', NULL, '岗位职责：1.进行储能系统相关产品的测试，包括产品开发验证测试、产品出厂测试、产品现场维护等；
