INSERT INTO job_postings (category_id, company_name, title, location, salary_text, source_url, raw_text, status, posted_at) VALUES ((SELECT id FROM job_categories WHERE name = '运维工程师/DevOps' LIMIT 1), '上海甦源能源科技有限公司', 'IT维护/运维', '上海-宝山区', '1.5-2千/月', NULL, '岗位职责
1、硬件维护主要包括PC机/笔记本电脑等终端设备的调配及维护并妥善记录；
2、通讯终端的管理包括电话、视频会议终端等设备的安装及管理，分配座机号及邮箱管理；
3、公司信息系统（OA系统、安全系统等）的选型、建设、管理和运维；
4、协助公司官网搭建及维护，域名管理；
任职资格
1、计算机或相关专业大专以上学历，按月外包；
2、3年以上桌面维护工作经验；掌握基本的网络知识；
3、熟悉网络软硬件产品，能进行基本的安装调试；
4、工作认真细心、沟通能力强、责任心强，有一定的数据分析、统计能力。', 'open', NULL);
INSERT INTO job_postings (category_id, company_name, title, location, salary_text, source_url, raw_text, status, posted_at) VALUES ((SELECT id FROM job_categories WHERE name = '运维工程师/DevOps' LIMIT 1), '广州怡境景观设计有限公司', '市场中心资源运维主管', '广州-天河区', '6-8千/月', NULL, '岗位职责：
1、根据公司具体的业务模式和产品模型，搭建资源管理系统；
2、负责公司市场资料的整理、归类、整理、建档和保管工作；
3、支持输出分析报告，包括业绩分析、市场研究、产品效果评估等，为营销策略、产品方向和运作支持方面提供发展建议。
任职要求：
1、数学、统计、金融等相关专业，全日制本科及以上学历；
2、熟悉SAS或SQL，具有数据分析、统计建模等经验优先；
3、能熟练操作使用PPT、EXCEL等各种办公软件；
4、具有敏锐的业务洞察力和数据分析技能，严谨的分析态度及逻辑思维能力。', 'open', NULL);
