INSERT INTO job_postings (category_id, company_name, title, location, salary_text, source_url, raw_text, status, posted_at) VALUES ((SELECT id FROM job_categories WHERE name = '前端开发工程师' LIMIT 1), '乐信集团', '前端岗（校招）', '深圳', '1.3-1.7万/月', NULL, '岗位职责：
