INSERT INTO job_postings (category_id, company_name, title, location, salary_text, source_url, raw_text, status, posted_at) VALUES ((SELECT id FROM job_categories WHERE name = '前端开发工程师' LIMIT 1), '思而科', '前端工程师', '成都', '0.5-1万/月', NULL, '岗位职责：完成电子商务网站前端开发工作；
