INSERT INTO job_postings (category_id, company_name, title, location, salary_text, source_url, raw_text, status, posted_at) VALUES ((SELECT id FROM job_categories WHERE name = '前端开发工程师' LIMIT 1), 'BIGO', '【2027届校园招聘】前端开发工程师-语音项目', '广州', NULL, NULL, '岗位职责 1. 负责 BIGO 创新产品 Web、H5 及 React Native 业务开发； 2. 基于 React、TypeScript 和 Rspack 建设前端架构，持续优化性能、质量和研发效率； 3. 采用 Coding Agent 驱动研发，完成需求分析、方案设计、编码、测试、评审和交付； 4. 将前端需求拆解为可执行的 Agent 任务，合理组织上下文、工具、Skills、MCP及多 Agent 协作； 5. 建设适合 Agent 执行的代码规范、组件体系、自动化测试、质量门禁和 CI/CD 流程； 6. 对 Agent 产出进行验证和验收，确保功能正确、代码可维护、性能达标且符合安全要求。 任职要求 1. 本科及以上学历，计算机或相关专业； 2. 具备扎实的 HTML、CSS、JavaScript/TypeScript 基础； 3. 熟悉 React、Hooks、状态管理及组件化设计，具备完整项目交付经验； 4. 熟悉 Rspack，掌握代码分割、缓存、产物分析及构建性能优化； 5. 熟悉 React Native，了解 iOS、Android 平台适配及性能优化； 6. 熟练使用 Codex、Claude Code、Cursor 等 Coding Agent，能够驱动 Agent 端到端完成前端需求； 7. 具备 Agentic Engineering 能力，包括任务拆解、上下文管理、工具编排、过程纠偏和结果验收； 8. 能够通过类型检查、自动化测试、代码评审、浏览器验收和 CI 门禁验证 Agent 产出，而非依赖人工直觉判断； 9. 能够识别并处理生成代码中的幻觉、错误假设、安全风险、过度实现及可维护性问题； 10. 具备良好的产品理解、架构判断、沟通协作和技术推动能力。 加分项 1. 有 MCP、Agent Skills、多 Agent 协作或自定义 Coding Agent 工作流经验； 2. 有使用 Agent 完成大型重构、框架迁移、测试补全或复杂缺陷修复的经验； 3. 熟悉 Node.js、Bun、Monorepo、自动化测试及 CI/CD； 4. 有 Rspack 插件、Module Federation 或微前端架构经验。', 'open', NULL);
