INSERT INTO job_postings (category_id, company_name, title, location, salary_text, source_url, raw_text, status, posted_at) VALUES ((SELECT id FROM job_categories WHERE name = '数据分析师' LIMIT 1), '第一创业证券', '财务分析岗', '深圳', '1-1.2万/月', NULL, '工作职责
