INSERT INTO job_postings (category_id, company_name, title, location, salary_text, source_url, raw_text, status, posted_at) VALUES ((SELECT id FROM job_categories WHERE name = '数据分析师' LIMIT 1), '快手', '财务分析实习生-本地生活', '北京', '3-5千/月', NULL, '负责事业部财务BP所有工作，包含熟悉平台各大区生态，全链路财务管理（进行预算管控，业财分析，业务决策支持，流程搭建与优化），你有机会参与长链条财务BP工作的全程~
