INSERT INTO job_postings (category_id, company_name, title, location, salary_text, source_url, raw_text, status, posted_at) VALUES ((SELECT id FROM job_categories WHERE name = '数据分析师' LIMIT 1), '百融智能', '数据分析师（校招/上海）', '上海', NULL, NULL, '岗位职责：
