INSERT INTO job_postings (category_id, company_name, title, location, salary_text, source_url, raw_text, status, posted_at) VALUES ((SELECT id FROM job_categories WHERE name = '大数据开发工程师' LIMIT 1), '阿里巴巴', '算法工程师-大数据处理-阿里巴巴2027届应届生', '全国', NULL, NULL, '1.构建集团核心数据资产体系，结合业务需求与数据算法能力，主导大数据的处理、解析、分析、挖掘、研发及优化工作；
