INSERT INTO job_postings (category_id, company_name, title, location, salary_text, source_url, raw_text, status, posted_at) VALUES ((SELECT id FROM job_categories WHERE name = '大数据开发工程师' LIMIT 1), '平安人寿', 'NS管培生（数据开发）', '深圳', '1-1.5万/月', NULL, '工作职责
