INSERT INTO job_postings (category_id, company_name, title, location, salary_text, source_url, raw_text, status, posted_at) VALUES ((SELECT id FROM job_categories WHERE name = '运维工程师/DevOps' LIMIT 1), '优景科技', '运维工程师', '上海', '6-7千/月', NULL, '岗位职责：
 

