INSERT INTO job_postings (category_id, company_name, title, location, salary_text, source_url, raw_text, status, posted_at) VALUES ((SELECT id FROM job_categories WHERE name = '运维工程师/DevOps' LIMIT 1), '阿里巴巴', 'AI Devops工程师-阿里巴巴2027届应届生', '全国', NULL, NULL, '1.深入参与芯片研发全生命周期的devops系统建设，搭建适用于pre-silicon、芯片回片、产品化的编译、测试、发布系统；
