INSERT INTO job_postings (category_id, company_name, title, location, salary_text, source_url, raw_text, status, posted_at) VALUES ((SELECT id FROM job_categories WHERE name = '网络安全工程师' LIMIT 1), '快手', '平台产品经理-内容安全', '北京', NULL, NULL, '1、负责各业务安全与风控平台的整体规划和设计，发掘业务方需求，高效支撑业务发展；
2、推进策略与模型管理、数据分析等相关系统工具的建设完善，提供快速决策支持；
