INSERT INTO job_postings (category_id, company_name, title, location, salary_text, source_url, raw_text, status, posted_at) VALUES ((SELECT id FROM job_categories WHERE name = '数据库管理员' LIMIT 1), '陕鼓集团', '管理类', '西安', NULL, NULL, '需求专业：企业管理、工商管理、统计学、公共关系管理、国际贸易、市场营销、营销管理、档案学、信息资源管理、英语等。

 基本条件

 (1) 2021-2023届统招毕业生，本科及以上学历；

 (2)双一流及一本院校；

 (3)英语要求：国内本科生通过四级，硕士生通过六级；海外雅思5分及以上，托福50分及以上；

 (4)成绩良好，无挂科；

 (5)身体健康，体检合格；

 (6)满足以下条件可优先录用：

 参加全国或行业大学生创意大赛等类赛事，项目获得二等奖以上奖项。

 具有专业方向的专利或影响度较高的论文发表。

 获得过国家级奖学金。

 校级学生会或校内颇有影响力社团的核心班子成员。

 有在行业标杆企业重要部门的实习或“管理训练营”等经历。

 有省市级“三好学生”、“十佳青年”等重要荣誉或见义勇为行为记录。

 研究课题与公司业务相关度强，且有研究成果或展示出较高的研究水平。', 'open', NULL);
INSERT INTO job_postings (category_id, company_name, title, location, salary_text, source_url, raw_text, status, posted_at) VALUES ((SELECT id FROM job_categories WHERE name = '数据库管理员' LIMIT 1), '苏州健客', '健康管理师', '苏州', '4-8千/月', NULL, '岗位职责：主要负责健康咨询、健康指导、健康理疗服务相关的工作。
1、负责顾客的接待、咨询、维护方面的工作。
2、建立健全顾客健康档案，定期维护与更新。
3、为顾客分析健康状况，分享各类健康、营养方面的养生知识，提供科学的健康养生指导。
4、为顾客提供基础的中医理疗服务（例如艾灸墨灸刮痧按摩）。
5、为顾客推荐适合的健康调理产品或制定健康管理解决方案，并跟进指导实施。
6、协助店长策划、组织、开展各类健康养生相关活动。

岗位基本要求：
1、性格活泼开朗，思维活跃，热爱大健康行业，认同公司企业文化。
2、具有耐心、爱心、责任心 ，有良好的沟通表达能力。
2、愿意学习中医相关的理疗服务（如艾灸、墨灸、刮痧、头部护理等），并给顾客进行操作。 
3、喜欢跟中老年人沟通，能接受跟中老年人相处交流。
4、医药相关专业，健康管理、营养学、中医中药学、中医康复、预防医学等专业优先考虑。
5、在校担任班委干部或有一定相关经验的优先考虑。
6、能接受做销售。', 'open', NULL);
