INSERT INTO job_postings (category_id, company_name, title, location, salary_text, source_url, raw_text, status, posted_at) VALUES ((SELECT id FROM job_categories WHERE name = '数据库管理员' LIMIT 1), '新希望服务', '客服管理岗', '杭州', '6-8千/月', NULL, '【岗位职责】
