INSERT INTO job_postings (category_id, company_name, title, location, salary_text, source_url, raw_text, status, posted_at) VALUES ((SELECT id FROM job_categories WHERE name = '数据库管理员' LIMIT 1), '平安普惠', '贷后管理', '重庆', '5-7千/月', NULL, '技能要求：
