INSERT INTO job_postings (category_id, company_name, title, location, salary_text, source_url, raw_text, status, posted_at) VALUES ((SELECT id FROM job_categories WHERE name = '数据库管理员' LIMIT 1), '启源芯动力', '电站运营管理', '上海', NULL, NULL, '岗位职责:
