INSERT INTO job_postings (category_id, company_name, title, location, salary_text, source_url, raw_text, status, posted_at) VALUES ((SELECT id FROM job_categories WHERE name = '移动开发工程师' LIMIT 1), 'TCL实业', 'Android应用工程师', '深圳', NULL, NULL, '岗位职责:
