INSERT INTO job_postings (category_id, company_name, title, location, salary_text, source_url, raw_text, status, posted_at) VALUES ((SELECT id FROM job_categories WHERE name = '移动开发工程师' LIMIT 1), '阿里巴巴', '客户端开发工程师Android-阿里巴巴2027届应届生', '全国', NULL, NULL, '1. 负责无线客户端和SDK产品的架构设计和开发工作；
2. 结合数据指标驱动和分析，不断深化无线客户端技术产品，优化客户端应用的性能以及提升客户端体验；
